        calls.append(val)
        return us.states.startswith_fallback(val)
    # a fallback hit is cached: the second call is served without re-invoking
    assert us.states.lookup("califo", fallback_func=counting_fallback) == california
    assert us.states.lookup("califo", fallback_func=counting_fallback) == california
    assert calls == ["califo"]

