def removeDuplicateLines(s: str) -> str:
    """Remove duplicate lines next to each other."""
    lines = s.split("\n")
    lines_out = []
    previous_line = ""
    for line in lines:
        if line != previous_line:
            lines_out.append(line)
            previous_line = line
    return "\n".join(lines_out)

