def _is_loopback_host(host: str) -> bool:
    """Return True if ``host`` is a loopback interface per RFC 8252."""
    host = host.strip("[]").lower()
    if host in LOOPBACK_HOSTS:
        return True
    try:
        return ipaddress.ip_address(host).is_loopback
    except ValueError:
        return False

