def _parse_bates_range(bates: str) -> tuple[str, int, int] | None:
    """Parse a Bates range like 'EFTA00039025-EFTA00039030'."""
    parts = bates.split("-")
    if len(parts) < 2:
        m = _BATES_PATTERN.match(parts[0].strip())
        if m:
            prefix, num_str = m.group(1), m.group(2)
            num = int(num_str)
            return (prefix, num, num)

