def backoff(function, *args, **kwargs):
    retries = 5
    def _():
        time.sleep(1)
        return function(*args, **kwargs)
    for attempt in range(retries):
        try:
            return _()
        except Exception as e:
            backoff = (attempt + 1) * 15

